 web.on("/brightness",HTTP_POST,[]{if(!web.hasArg("idle")||!web.hasArg("success")||!web.hasArg("duration")){web.send(400,"text/plain","Missing brightness settings");return;}idleBrightness=constrain(web.arg("idle").toInt(),0L,100L);successBrightness=constrain(web.arg("success").toInt(),0L,100L);confirmMs=constrain(web.arg("duration").toInt(),20L,500L);prefs.putUInt("idlePWM",idleBrightness);prefs.putUInt("scanPWM",successBrightness);prefs.putUInt("flashMs",confirmMs);if(!whiteUntil)applyBrightness(ledOn?idleBrightness:0);web.send(200,"text/plain","OK");});
 web.on("/power",HTTP_POST,[]{if(workerBusy||asleep){web.send(409,"text/plain","Wake camera or wait for decoder");return;}if(!web.hasArg("cpu")||!web.hasArg("sleep")||!web.hasArg("jpeg")){web.send(400,"text/plain","Missing settings");return;}unsigned mhz=web.arg("cpu").toInt();int jq=web.arg("jpeg").toInt();if((mhz!=80&&mhz!=160&&mhz!=240)||jq<8||jq>30){web.send(400,"text/plain","Invalid settings");return;}sensor_t *s=esp_camera_sensor_get();if(!s||s->set_quality(s,jq)!=0){web.send(500,"text/plain","JPEG setting failed");return;}jpegQuality=jq;if(!setCpuFrequencyMhz(mhz)){web.send(500,"text/plain","CPU setting failed");return;}cpuMHz=getCpuFrequencyMhz();wifiPowerSave=web.arg("sleep")=="1";WiFi.setSleep(wifiPowerSave);web.send(200,"text/plain","OK");});
