 web.on("/status",HTTP_GET,[]{String out="{\"camera\":"+jsString(camStatus)+",\"ip\":"+jsString(WiFi.status()==WL_CONNECTED?WiFi.localIP().toString():WiFi.softAPIP().toString())+",\"wifi\":"+jsString(WiFi.status()==WL_CONNECTED?"Connected":"Setup mode")+",\"count\":"+String(count)+",\"operator\":"+jsString(activeOperator)+",\"operatorName\":"+jsString(activeOperatorName)+",\"otaReady\":"+(otaReady?"true":"false")+",\"appSlot\":"+jsString(esp_ota_get_running_partition()->label)+",\"asleep\":"+(asleep?"true":"false")+",\"autoStandby\":"+(autoStandby?"true":"false")+",\"nativePeriod\":"+String(nativePeriod)+",\"heap\":"+String(ESP.getFreeHeap())+",\"psram\":"+String(ESP.getFreePsram())+",\"uptime\":"+String(millis())+",\"journalReady\":"+(journalReady?"true":"false")+",\"journalError\":"+jsString(journalError)+",\"engine\":"+jsString(decodeMode)+",\"nativeValue\":"+jsString(nativeValue)+",\"nativeFormat\":"+jsString(nativeFormat)+",\"nativeError\":"+jsString(nativeError)+",\"nativeMs\":"+String(nativeMs)+",\"nativeFrames\":"+String(nativeFrames)+",\"cpuMHz\":"+String(cpuMHz)+",\"wifiPowerSave\":"+(wifiPowerSave?"true":"false")+",\"jpegQuality\":"+String(jpegQuality)+",\"idleBrightness\":"+String(idleBrightness)+",\"successBrightness\":"+String(successBrightness)+",\"confirmMs\":"+String(confirmMs)+",\"resolution\":"+jsString(scanResolution)+",\"pendingResolution\":"+jsString(pendingResolution)+",\"resolutionError\":"+jsString(resolutionError)+",\"rotation\":"+String(rotation)+",\"led\":"+(ledOn?"true":"false")+",\"capture\":"+jsString(captureState)+",\"focus\":"+jsString(focusState)+",\"scans\":[";unsigned n=min(count,50u);for(unsigned i=0;i<n;i++){if(i)out+=",";out+=jsString(history[(count-1-i)%50]);}out+="],\"boot\":"+String(bootId)+",\"records\":[";for(unsigned j=0;j<n;j++){unsigned id=count-j,i=(id-1)%50;if(j)out+=",";out+="{\"id\":"+String(id)+",\"format\":"+jsString(recordFormat[i])+",\"raw\":"+jsString(recordRaw[i])+",\"uptime\":"+String(recordUptime[i])+",\"time\":"+jsString(recordTime[i])+",\"operator\":"+jsString(recordOperator[i])+"}";}out+="]}";web.send(200,"application/json",out);});
 web.on("/frame",HTTP_GET,[]{if(workerBusy){web.send(425,"text/plain","Native busy");return;}if(asleep){if(!cameraWake()){web.send(503,"text/plain","Camera wake failed");return;}}lastActivity=millis();if(whiteUntil){web.send(425,"text/plain","Scan confirmation");return;}if(camStatus!="Ready"){web.send(503,"text/plain",camStatus);return;}uint32_t captureStart=micros();camera_fb_t *f=esp_camera_fb_get();uint32_t acquisitionUs=micros()-captureStart;if(!f){web.send(503,"text/plain","No frame");return;}if(decodeMode=="compare"){nativeDecode(f);String hex;for(unsigned i=0;i<nativeValue.length();i++){char b[3];snprintf(b,sizeof(b),"%02x",(unsigned char)nativeValue[i]);hex+=b;}web.sendHeader("X-Native-Hex",hex);web.sendHeader("X-Native-Ms",String(nativeMs));}web.sendHeader("Cache-Control","no-store");web.sendHeader("X-Acquisition-Ms",String(acquisitionUs/1000.0,2));web.sendHeader("X-Camera-Timestamp-Us",String((double)f->timestamp.tv_sec*1000000.0+f->timestamp.tv_usec,0));web.setContentLength(f->len);web.send(200,"image/jpeg","");web.client().write(f->buf,f->len);esp_camera_fb_return(f);});
