static void networkLoop(){
 if(restartPending&&(int32_t)(millis()-restartAt)>=0)ESP.restart();
 if(WiFi.status()==WL_CONNECTED){
 if(!mdnsOn){mdnsOn=MDNS.begin(host);if(mdnsOn)MDNS.addService("http","tcp",80);Serial.printf("WiFi: %s | http://%s/\n",WiFi.localIP().toString().c_str(),WiFi.localIP().toString().c_str());}
 if(apOn){WiFi.softAPdisconnect(true);WiFi.mode(WIFI_STA);apOn=false;}
 }else{if(mdnsOn){MDNS.end();mdnsOn=false;connectStart=millis();}if(!apOn&&millis()-connectStart>15000)startAP();}
 if(WiFi.status()==WL_CONNECTED&&!otaReady){ArduinoOTA.setHostname(host);ArduinoOTA.setPassword(otaPassword.c_str());ArduinoOTA.onStart([](){otaActive=true;applyBrightness(0);});ArduinoOTA.onError([](ota_error_t){otaActive=false;applyBrightness(ledOn?idleBrightness:0);});ArduinoOTA.begin();otaReady=true;}
 if(!workerBusy)ArduinoOTA.handle();
 if(!otaActive)web.handleClient();
}
